// Generated by AI (UnitTest MCP)
use std::{
    fs,
    path::{Path, PathBuf},
    sync::atomic::{AtomicU64, Ordering},
};

use ackplane_protocol::{
    supervisor::{
        SupervisorCapabilities, SupervisorDirectiveCapability, SupervisorIdentity,
        SupervisorOutboxDurability, SupervisorRegistration, SupervisorRuntime, SupervisorSession,
        SupervisorWorkerState,
    },
    v1::{self, node_frame},
};
use ackplane_supervisor::{OutboxError, QueueOutcome, SupervisorOutbox};

static NEXT_DATABASE: AtomicU64 = AtomicU64::new(1);

fn database_path(label: &str) -> PathBuf {
    let sequence = NEXT_DATABASE.fetch_add(1, Ordering::Relaxed);
    std::env::temp_dir().join(format!(
        "ackplane-supervisor-outbox-{label}-{}-{sequence}.db",
        std::process::id()
    ))
}

fn remove_database(path: &Path) {
    for suffix in ["", "-wal", "-shm"] {
        let _ = fs::remove_file(format!("{}{}", path.display(), suffix));
    }
}

fn registration() -> SupervisorRegistration {
    SupervisorRegistration {
        supervisor_id: "supervisor-a".to_string(),
        identity: SupervisorIdentity {
            tenant_id: "tenant-a".to_string(),
            repository_id: "repository-a".to_string(),
            node_id: "node-a".to_string(),
        },
        supervisor_version: "1.0.0".to_string(),
        protocol_version: "v1".to_string(),
        capabilities: SupervisorCapabilities {
            supported_directives: vec![SupervisorDirectiveCapability::Prompt],
            supports_checkpoint: true,
            supports_force_termination: false,
            outbox_durability: SupervisorOutboxDurability::Persistent,
            recoverable_outbox: true,
        },
    }
}

fn session() -> SupervisorSession {
    SupervisorSession {
        session_id: "session:v1:agent-a".to_string(),
        supervisor_id: "supervisor-a".to_string(),
        worker_id: "worker-a".to_string(),
        runtime: SupervisorRuntime::Pipeline,
        started_at: 1_700_000_000,
        state: SupervisorWorkerState::Started,
    }
}

fn heartbeat(position: u64) -> v1::NodeFrame {
    v1::NodeFrame {
        frame: Some(node_frame::Frame::Heartbeat(v1::Heartbeat {
            last_accepted_position: position,
        })),
    }
}

#[test]
fn queued_frame_survives_reopening_the_same_outbox() {
    let path = database_path("reopen");
    remove_database(&path);
    let frame = heartbeat(10);

    {
        let outbox = SupervisorOutbox::open(&path, registration(), session()).expect("open outbox");
        assert_eq!(
            outbox.enqueue(1, &frame).expect("queue frame"),
            QueueOutcome::Queued
        );
    }

    let outbox = SupervisorOutbox::open(&path, registration(), session()).expect("reopen outbox");
    assert_eq!(
        outbox.pending(10).expect("read pending frames"),
        vec![ackplane_supervisor::QueuedFrame { sequence: 1, frame }]
    );
    drop(outbox);
    remove_database(&path);
}

#[test]
fn identical_enqueue_replays_without_duplicating_the_frame() {
    let path = database_path("replay");
    remove_database(&path);
    let outbox = SupervisorOutbox::open(&path, registration(), session()).expect("open outbox");
    let frame = heartbeat(10);

    assert_eq!(
        outbox.enqueue(1, &frame).expect("queue first frame"),
        QueueOutcome::Queued
    );
    assert_eq!(
        outbox.enqueue(1, &frame).expect("replay first frame"),
        QueueOutcome::Replayed
    );
    assert_eq!(outbox.pending(10).expect("read pending frames").len(), 1);
    drop(outbox);
    remove_database(&path);
}

#[test]
fn changed_frame_at_existing_sequence_is_refused_without_overwrite() {
    let path = database_path("collision");
    remove_database(&path);
    let outbox = SupervisorOutbox::open(&path, registration(), session()).expect("open outbox");
    let original = heartbeat(10);
    let changed = heartbeat(11);

    outbox.enqueue(1, &original).expect("queue original frame");
    assert!(matches!(
        outbox.enqueue(1, &changed),
        Err(OutboxError::FrameConflict { sequence: 1 })
    ));
    assert_eq!(
        outbox.pending(10).expect("read pending frames")[0].frame,
        original
    );
    drop(outbox);
    remove_database(&path);
}

#[test]
fn zero_and_gapped_sequences_do_not_consume_the_next_outbox_slot() {
    let path = database_path("sequence");
    remove_database(&path);
    let outbox = SupervisorOutbox::open(&path, registration(), session()).expect("open outbox");

    assert!(matches!(
        outbox.enqueue(0, &heartbeat(0)),
        Err(OutboxError::SequenceMustBePositive)
    ));
    match outbox.enqueue(2, &heartbeat(20)) {
        Err(OutboxError::SequenceGap { expected, received }) => {
            assert_eq!((expected, received), (1, 2));
        }
        unexpected => panic!("expected sequence gap, got {unexpected:?}"),
    }
    assert_eq!(
        outbox
            .enqueue(1, &heartbeat(10))
            .expect("queue first frame"),
        QueueOutcome::Queued
    );
    drop(outbox);
    remove_database(&path);
}

#[test]
fn pending_frames_are_ordered_and_bounded() {
    let path = database_path("pending");
    remove_database(&path);
    let outbox = SupervisorOutbox::open(&path, registration(), session()).expect("open outbox");
    for sequence in 1..=3 {
        outbox
            .enqueue(sequence, &heartbeat(sequence * 10))
            .expect("queue frame");
    }

    let pending = outbox.pending(2).expect("read bounded pending frames");

    assert_eq!(
        pending
            .iter()
            .map(|queued| queued.sequence)
            .collect::<Vec<_>>(),
        vec![1, 2]
    );
    assert!(matches!(
        outbox.pending(0),
        Err(OutboxError::NonPositiveLimit)
    ));
    drop(outbox);
    remove_database(&path);
}

#[test]
fn acknowledgement_prunes_only_frames_through_the_acknowledged_sequence() {
    let path = database_path("acknowledge");
    remove_database(&path);
    let outbox = SupervisorOutbox::open(&path, registration(), session()).expect("open outbox");
    for sequence in 1..=3 {
        outbox
            .enqueue(sequence, &heartbeat(sequence * 10))
            .expect("queue frame");
    }

    assert_eq!(
        outbox.acknowledge_through(2).expect("acknowledge frames"),
        2
    );
    assert_eq!(
        outbox
            .pending(10)
            .expect("read remaining frames")
            .into_iter()
            .map(|queued| queued.sequence)
            .collect::<Vec<_>>(),
        vec![3]
    );
    drop(outbox);
    remove_database(&path);
}

// Acknowledgement deletes historical rows, so the durable sequence high-water must survive it.
#[test]
fn acknowledgement_pruning_preserves_the_next_sequence_after_reopen() {
    let path = database_path("acknowledge-reopen");
    remove_database(&path);
    let first = heartbeat(10);
    let next = heartbeat(20);

    {
        let outbox = SupervisorOutbox::open(&path, registration(), session()).expect("open outbox");
        outbox.enqueue(1, &first).expect("queue first frame");
        assert_eq!(
            outbox
                .acknowledge_through(1)
                .expect("acknowledge first frame"),
            1
        );
    }

    let outbox = SupervisorOutbox::open(&path, registration(), session()).expect("reopen outbox");
    assert_eq!(
        outbox.enqueue(2, &next).expect("queue next frame"),
        QueueOutcome::Queued
    );
    assert_eq!(
        outbox.pending(10).expect("read pending frames"),
        vec![ackplane_supervisor::QueuedFrame {
            sequence: 2,
            frame: next,
        }]
    );
    drop(outbox);
    remove_database(&path);
}
